// =========================================================================
// الحزمة الصوتية الرسمية لمنصة مسابقات الدراسات الإسلامية
// بصوت القارئ الفصيح المعتمد (حامد - النبرة السعودية الفصيحة)
// يشمل التغذية الراجعة الفورية وقارئ الأسئلة والخيارات
// تصميم: محمد آل حسين | لصالح متوسطة العفج
// =========================================================================

const VOICE_ASSETS = {
    correct: "data:audio/mp3;base64,",
    retry: "data:audio/mp3;base64,",
    wrong: "data:audio/mp3;base64,"
};

let currentFeedbackAudio = null;
let isSpeakingQuestion = false;

// تشغيل الصوت الفوري للتغذية الراجعة (أحسنت / تأكد ولديك فرصة ثانية / خطأ)
function playVoiceFeedback(type) {
    if (typeof appState !== 'undefined' && !appState.soundEnabled) return;
    try {
        // إيقاف قراءة السؤال إن كانت جارية حتى يُسمع صوت التغذية الراجعة بوضوح
        stopVoiceReading();

        if (currentFeedbackAudio) {
            currentFeedbackAudio.pause();
            currentFeedbackAudio.currentTime = 0;
        }

        const src = VOICE_ASSETS[type];
        if (src) {
            currentFeedbackAudio = new Audio(src);
            currentFeedbackAudio.play().catch(err => {
                console.warn('Audio play prevented:', err);
                fallbackSpeakFeedback(type);
            });
        } else {
            fallbackSpeakFeedback(type);
        }
    } catch (e) {
        console.error('Error playing voice feedback:', e);
        fallbackSpeakFeedback(type);
    }
}

function fallbackSpeakFeedback(type) {
    if (!('speechSynthesis' in window)) return;
    let phrase = "أَحْسَنْتَ!";
    if (type === 'retry') phrase = "تَأَكَّدْ يَا بَطَلْ! لَدَيْكَ فُرْصَةٌ ثَانِيَةٌ، حَاوِلْ مَرَّةً أُخْرَى.";
    if (type === 'wrong') phrase = "إِجَابَةٌ خَاطِئَةٌ! خَيْرُهَا فِي غَيْرِهَا يَا بَطَلْ.";
    
    const utter = new SpeechSynthesisUtterance(phrase);
    utter.lang = 'ar-SA';
    utter.rate = 0.9;
    window.speechSynthesis.speak(utter);
}

// قراءة نص السؤال والخيارات بالتتابع بصوت القارئ الفصيح
function speakQuestionAndOptions(title, options, onStart, onEnd) {
    if (!('speechSynthesis' in window)) return;
    window.speechSynthesis.cancel();

    // صياغة النص الإذاعي التعليمي الواضح
    let fullText = "السُّؤَالُ: " + title + " ... ";
    if (options && options.length === 4) {
        fullText += "الْخِيَارُ الأَوَّلُ: " + options[0] + " ... ";
        fullText += "الْخِيَارُ الثَّانِي: " + options[1] + " ... ";
        fullText += "الْخِيَارُ الثَّالِثُ: " + options[2] + " ... ";
        fullText += "الْخِيَارُ الرَّابِعُ: " + options[3];
    }

    const utter = new SpeechSynthesisUtterance(fullText);
    utter.lang = 'ar-SA';
    utter.rate = 0.88; // سرعة تعليمية رصينة وواضحة
    utter.pitch = 1.0;

    // انتقاء أفضل صوت عربي متاح في متصفح المستخدم
    const voices = window.speechSynthesis.getVoices();
    const bestVoice = voices.find(v => v.lang.startsWith('ar') && (
        v.name.includes('Natural') || v.name.includes('Hamed') || v.name.includes('Shakir') || 
        v.name.includes('Naayf') || v.name.includes('Saudi') || v.name.includes('Google')
    )) || voices.find(v => v.lang.startsWith('ar')) || voices.find(v => v.lang.includes('ar'));

    if (bestVoice) {
        utter.voice = bestVoice;
    }

    utter.onstart = () => {
        isSpeakingQuestion = true;
        if (onStart) onStart();
    };

    utter.onend = () => {
        isSpeakingQuestion = false;
        if (onEnd) onEnd();
    };

    utter.onerror = () => {
        isSpeakingQuestion = false;
        if (onEnd) onEnd();
    };

    window.speechSynthesis.speak(utter);
}

function stopVoiceReading() {
    if ('speechSynthesis' in window) {
        window.speechSynthesis.cancel();
    }
    isSpeakingQuestion = false;
}
